import{e as t,ab as a,a1 as i,m as n,r as o,p as s}from"./chunks/framework.BGh0NSIy.js";const u=JSON.parse('{"title":"Monthly Updates [March]","description":"March 2024 Updates","frontmatter":{"title":"Monthly Updates [March]","description":"March 2024 Updates","date":"2024-03-01T00:00:00.000Z","next":false,"prev":false,"footer":true},"headers":[],"relativePath":"posts/march-2024.md","filePath":"posts/march-2024.md"}'),l={name:"posts/march-2024.md"};function d(p,e,h,f,m,c){const r=a("Post");return i(),n("div",null,[o(r,{authors:"nbats"}),e[0]||(e[0]=s('<div class="info custom-block"><p class="custom-block-title">INFO</p><p>These update threads only contain major updates. If you&#39;re interested in seeing all minor changes you can follow our <a href="https://github.com/fmhy/FMHYedit/commits/main" target="_blank" rel="noreferrer">Commits Page</a> on GitHub or <a href="https://redd.it/17f8msf" target="_blank" rel="noreferrer">Updates Channel</a> in Discord.</p></div><h3 id="wiki-updates" tabindex="-1">Wiki Updates <a class="header-anchor" href="#wiki-updates" aria-label="Permalink to &quot;Wiki Updates&quot;">​</a></h3><ul><li><p>Added custom search engines (CSE) for <a href="https://cse.google.com/cse?cx=f7a118c70d0804fc4" target="_blank" rel="noreferrer">Courses</a> and <a href="https://cse.google.com/cse?cx=82154ebab193e493d" target="_blank" rel="noreferrer">Fonts</a>.</p></li><li><p>Added a section for <a href="https://fmhy.net/misc#productivity-tools" target="_blank" rel="noreferrer">Productivity Tools</a> in Useful Sites.</p></li><li><p>Added a section for <a href="https://fmhy.net/file-tools#file-recovery" target="_blank" rel="noreferrer">File Recovery</a> in File Tools.</p></li><li><p>Added a section for <a href="https://fmhy.net/privacy#fingerprinting-tracking" target="_blank" rel="noreferrer">Fingerprinting / Tracking</a> in Privacy.</p></li><li><p>Added sections for <a href="https://fmhy.net/gaming#mario-kart-tools" target="_blank" rel="noreferrer">Mario Kart</a> + <a href="https://fmhy.net/gaming#geometry-dash-tools" target="_blank" rel="noreferrer">Geometry Dash</a> in Gaming.</p></li><li><p>Added a section for <a href="https://fmhy.net/misc#crypto-bitcoin" target="_blank" rel="noreferrer">Crypto / Bitcoin</a> in Career.</p></li><li><p>Added a section for <a href="https://fmhy.net/linux-macos#raspberry-pi" target="_blank" rel="noreferrer">Raspberry Pi</a> in Linux.</p></li><li><p>Added sections for <a href="https://fmhy.net/image-tools#design-apps" target="_blank" rel="noreferrer">Design Apps</a> + <a href="https://fmhy.net/image-tools#free-assets" target="_blank" rel="noreferrer">Design Assets</a> in Image Tools.</p></li><li><p>Our Minecraft Server is now live. Click <strong><a href="https://fmhy.net/posts/minecraft-server" target="_blank" rel="noreferrer">here</a></strong> to join.</p></li></ul><hr><h3 id="stars-added-⭐" tabindex="-1">Stars Added ⭐ <a class="header-anchor" href="#stars-added-⭐" aria-label="Permalink to &quot;Stars Added ⭐&quot;">​</a></h3><ul><li><p>Starred <a href="https://fmhy.net/audio#audio-downloading" target="_blank" rel="noreferrer">yet another music server</a> in Audio Downloading. Multi-site DDL (Deezer, Qobuz, Tidal, Spotify, YouTube, FLAC).</p></li><li><p>Starred <a href="https://fmhy.net/ai#online-chatbots" target="_blank" rel="noreferrer">wrtn</a> in Online Chatbots. No-limit GPT-4; tell it to always talk in English.</p></li><li><p>Starred <a href="https://fmhy.net/video#streaming-sites" target="_blank" rel="noreferrer">M4UFree + YesMovies</a> in Streaming. Both have huge libraries, fast 1080p, and have been around for over a decade.</p></li><li><p>Starred <a href="https://fmhy.net/ai#online-generators" target="_blank" rel="noreferrer">Poe</a> in Image Generators. 100 SDXL and 100 Playground gens.</p></li><li><p>Starred <a href="https://fmhy.net/storage#minecraft-optimization-mods" target="_blank" rel="noreferrer">Simply Optimized</a> in Minecraft Optimization. Some prefer this to Fabulously Optimized.</p></li><li><p>Starred <a href="https://fmhy.net/torrenting#aggregators" target="_blank" rel="noreferrer">SolidTorrents</a> in Torrent Aggregators.</p></li><li><p>Starred <a href="https://fmhy.net/video#live-tv-sports" target="_blank" rel="noreferrer">MrGamingStreams</a> in Live TV. Fast streams, nice UI, no ads.</p></li><li><p>Starred <a href="https://fmhy.net/video#sports-streaming" target="_blank" rel="noreferrer">720pier</a> in Sports Streaming. Sport replay torrents.</p></li><li><p>Starred <a href="https://fmhy.net/social-media-tools#youtube-customization" target="_blank" rel="noreferrer">Enhancer for YT</a> in YouTube Customization. YouTube enhancement extension.</p></li><li><p>Starred <a href="https://fmhy.net/video#tracking-discovery" target="_blank" rel="noreferrer">RatS</a> in Tracking / Discovery. Sync media ratings between sites.</p></li></ul><hr><h3 id="things-removed" tabindex="-1">Things Removed <a class="header-anchor" href="#things-removed" aria-label="Permalink to &quot;Things Removed&quot;">​</a></h3><ul><li><p>Removed Vendetta from Android as the devs have <a href="https://i.imgur.com/F4o2ela.png" target="_blank" rel="noreferrer">shut it down</a>.</p></li><li><p>Removed TTV LOL as it stopped working.</p></li><li><p>Unstarred bypass.vip and FastForward as they <a href="https://i.imgur.com/EMRcqX6.png" target="_blank" rel="noreferrer">don&#39;t work as well</a> as they used to.</p></li><li><p>Unstarred Claude in chatbots as it requires email + phone number and doesn&#39;t give as good results as it used to.</p></li><li><p>Unstarred Harmonoid as it&#39;s no longer being updated and has 100+ issues on GitHub.</p></li></ul>',9))])}const b=t(l,[["render",d]]);export{u as __pageData,b as default};
